import{_ as e,c as t,o as a,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"DELIVERING MOST-FAVORED-NATION PRESCRIPTION DRUG","description":"","frontmatter":{"title":"DELIVERING MOST-FAVORED-NATION PRESCRIPTION DRUG","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/delivering-most-favored-nation-prescription-drug-pricing-to-american-patients/","publishDate":"2025-05-12T11:29:35-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-12-delivering-most-favored-nation-prescription-drug.md","filePath":"executive-orders/2025-05-12-delivering-most-favored-nation-prescription-drug.md"}'),n={name:"executive-orders/2025-05-12-delivering-most-favored-nation-prescription-drug.md"};function o(s,i,l,c,p,d){return a(),t("div",null,i[0]||(i[0]=[r('<h1 id="delivering-most-favored-nation-prescription-drug" tabindex="-1">DELIVERING MOST-FAVORED-NATION PRESCRIPTION DRUG <a class="header-anchor" href="#delivering-most-favored-nation-prescription-drug" aria-label="Permalink to &quot;DELIVERING MOST-FAVORED-NATION PRESCRIPTION DRUG&quot;">​</a></h1><p>Published: Monday, May 12, 2025</p><ul><li>The U.S. funds a disproportionate amount of global pharmaceutical profits while comprising less than 5% of the world&#39;s population.</li><li>Drug manufacturers often heavily discount products for foreign markets, compensating for this by charging significantly higher prices in the U.S.</li><li>American consumers have been unfairly subsidizing the cost of pharmaceuticals for other countries while facing inflated prices domestically.</li><li>The Executive Order aims to grant Americans access to the most-favored-nation pricing for pharmaceuticals, aligning U.S. prices with those of comparably developed nations.</li><li>Immediate actions will be taken to combat &quot;global freeloading&quot; by pharmaceutical manufacturers, with a commitment to aggressive measures if compliance with pricing standards is not met.</li><li>The Secretary of Commerce and the U.S. Trade Representative are tasked with ensuring foreign practices do not undermine U.S. national security or impose unreasonable costs on American patients.</li><li>The Secretary of Health and Human Services will facilitate programs allowing consumers to purchase drugs at the most-favored-nation price.</li><li>Within 30 days, the Secretary will communicate pricing targets to pharmaceutical manufacturers; subsequent actions will follow if significant progress isn&#39;t achieved.</li><li>Potential actions outlined include: <ul><li>Implementing a rulemaking plan for most-favored-nation pricing.</li><li>Considering drug importation from low-cost countries if legally justifiable.</li><li>Enforcing against anti-competitive practices as identified in an upcoming report.</li><li>Reviewing pharmaceutical exports that contribute to price discrimination.</li><li>Assessing drug approvals regarding safety and effectiveness.</li></ul></li><li>The order clarifies that it does not alter the authorities of any executive department or agency.</li><li>Implementation remains subject to applicable law and funding availability.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/delivering-most-favored-nation-prescription-drug-pricing-to-american-patients/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/delivering-most-favored-nation-prescription-drug-pricing-to-american-patients/</a></p>',4)]))}const g=e(n,[["render",o]]);export{m as __pageData,g as default};
